data.value:
        double vleraMeZbritjeTot = 0.00;
        double sasiaTot = 0.00;
        double kmshtotale = 0.00;
        double kmshtotalegrup = 0.00;
        double sasiatotale = 0.00;
        double sasiatotalegrup = 0.00;
        private double marzhiBrutoMeZbritje = 0;
        private double marzhiBrutoMeZbritjeGrup = 0;
        private double vleraShitjesMeZbritje = 0;


private void xrLabel1_AfterPrint(object sender, System.EventArgs e) {
	if (GetCurrentColumnValue("SASIA") != null)
            {
                sasiatotale = sasiatotale + Convert.ToDouble(GetCurrentColumnValue("SASIA"));                
            }
}

private void xrLabel6_AfterPrint(object sender, System.EventArgs e) {
	double vl;
            if (xrLabel6.Text == "" || xrLabel5.Text == null)
            {
                vl = 0;
            }
            else
            {
                vl = Convert.ToDouble(xrLabel6.Text);
            }
            marzhiBrutoMeZbritje = marzhiBrutoMeZbritje + vl; 
}

private void xrLabel5_AfterPrint(object sender, System.EventArgs e) {
	double vl;
            if (xrLabel5.Text == "" || xrLabel5.Text == null)
            {
                vl = 0;
            }
            else
            {
                vl = Convert.ToDouble(xrLabel5.Text);
            }
            vleraShitjesMeZbritje = vleraShitjesMeZbritje + vl;
}

private void xrLabel3_AfterPrint(object sender, System.EventArgs e) {
	if (GetCurrentColumnValue("VLERASHITJESPATVSH") != null && GetCurrentColumnValue("SASIA") != null)
            {
                kmshtotale = kmshtotale + Convert.ToDouble(GetCurrentColumnValue("VLERASHITJESPATVSH")) * Convert.ToDouble(GetCurrentColumnValue("SASIA"));
            }
}

private void MarzhiPerqindjeTotali_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	if (vleraShitjesMeZbritje != 0)
            {
                MarzhiPerqindjeTotali.Text = String.Format("{0:#,#.00}", (marzhiBrutoMeZbritje / vleraShitjesMeZbritje) * 100);
            }
            else
                MarzhiPerqindjeTotali.Text = String.Format("{0:#,#.00}",0);
}

private void xrLabel37_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
		e.Result = String.Format("{0:#,#.00}", (vleraMeZbritjeTot / sasiaTot));
            e.Handled = true;
}

private void xrLabel37_SummaryReset(object sender, System.EventArgs e) {
		sasiaTot = 0.00;
            vleraMeZbritjeTot = 0.00;
}

private void xrLabel37_SummaryRowChanged(object sender, System.EventArgs e) {
		if (GetCurrentColumnValue("VLERAMEZBRITJE") != null && GetCurrentColumnValue("SASIA") != null)
            {

                vleraMeZbritjeTot = vleraMeZbritjeTot + Convert.ToDouble(GetCurrentColumnValue("VLERAMEZBRITJE"));
                sasiaTot = sasiaTot + Convert.ToDouble(GetCurrentColumnValue("SASIA"));
            }
}

private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

}
private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
AlphaWebReports.raporteUtil.shtoFiltra(filtraTable, null, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));
}

private void Rap_MarzhiShitjeveMagazina_NjesiPerberesi_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
}
